\label{ass::Lipschitz}
	The function $f$ in~\eqref{eq::ode_base} is continuous. Besides, it is Lipschitz-continuous with respect to the second argument, i.e., there exists a constant $L>0$ such that
	\begin{displaymath}
		\|f(t,x)-f(t,y)\|\leq L\|x-y\|
	\end{displaymath}
	for all $t\in\mathbb{T}$ and all $x,y\in\ensuremath\mathbb{R}^n$.

\label{thm::core_result}
	Suppose $f$ in~\eqref{eq::ode_base} satisfies Assumption~\ref{ass::Lipschitz} and the ML candidate function $\hat{\varphi}$ is sufficiently smooth. For any continuous function $\delta\colon\mathbb{T}\to\ensuremath\mathbb{R}_+$ with
	\begin{equation}
		\label{eq::upper_bound_residual}
		\|\mathcal{R}_{\hat{\varphi}}(t)\| \leq \delta(t)
	\end{equation}
	define 
	\begin{equation*}
		I(t,\delta)\vcentcolon=\int_{0}^t \mathrm{e}^{L(t-s)}\delta(s)\,\mathrm{d}s,
	\end{equation*}
	where $L$ is the Lipschitz constant from Assumption~\ref{ass::Lipschitz}.
	Then the ML prediction error~\eqref{eq::ml_error} satisfies
	\begin{equation}
		\label{eq::fund_lemma_stat}
		|| e(t) || \leq \mathrm{e}^{L t} \|x_0-\hat{x}(0)\| + I(t,\delta).
	\end{equation}

Let $\hat{x}_0 \vcentcolon= \hat{x}(0)$. Assumption~\ref{ass::Lipschitz} together with the smoothness of $\hat{\varphi}$ implicates that $\mathcal{R}_{\hat{\varphi}}$ is continuous. Then, Assumption~\ref{ass::Lipschitz} implies that $\hat{x}$ is the unique solution of the perturbed initial value problem
	\begin{equation}
		\label{eq::ode_perturbed}
		\begin{aligned}
		\dot{\hat{x}}(t) &= f(t,\hat{x}(t)) + \mathcal{R}_{\hat{\varphi}}(t), & t\in\mathbb{T}, \\
		\hat{x}(0) &= \hat{x}_0.
		\end{aligned}
	\end{equation}
	The result is thus an immediate consequence of \cite[Ch.~I, Variant of Thm.~10.2]{HaiNW08}.

Theorem~\ref{thm::core_result} can be easily generalized for time dependent Lipschitz parameters 
    \begin{equation*}
        || f(t, x) - f(t, y) || \le \ell(t) || x-y||
    \end{equation*}
    by replacing the exponent $Lt$ by $L(t)=\int_0^t \ell(s)\,\mathrm{d}s$ in~\eqref{eq::fund_lemma_stat}.

\label{thm::linear_rhs}
	Suppose that the right-hand side of~\eqref{eq::ode_base} is linear, i.e., given by~\eqref{eq::ode_linear}, and $\hat{\varphi}$ is sufficiently smooth. 
	Then there exist constants $\alpha \in\ensuremath\mathbb{R}$, $\beta\in\ensuremath\mathbb{R}_+$ such that for any continuous function $\delta\colon\mathbb{T}\to\ensuremath\mathbb{R}$ with
	\begin{displaymath}
		\|\mathcal{R}_{\hat{\varphi}}(t)\| \leq \delta(t),
	\end{displaymath}
	the ML prediction error satisfies
	\begin{equation}
		\label{eq::improvedErrLinear}		
		\resizebox{.98\linewidth}{!}{$\begin{aligned}
		|| e(t)  || \leq \beta \left(\mathrm{e}^{\alpha t}\|x_0 -\hat{x}(0)\| + \int_{0}^t \mathrm{e}^{\alpha(t-s)}\delta(s)\,\mathrm{d}s\right).
		\end{aligned}$}
	\end{equation}

\textcolor{red}{Corrected}
	Subtracting \eqref{eq::ode_perturbed} from \eqref{eq::ode_base} yields the error dynamics
	\begin{equation}
		\label{eq::ode_errorDynamics}
		\begin{aligned}
		\dot{e}(t) &= Ae(t) + \mathcal{R}_{\hat{\varphi}}(t), & t\in\mathbb{T}, \\
		e(0) &= x_0 - \hat{x}_0.
		\end{aligned}
	\end{equation}
	Its unique solution is given by 
	\begin{displaymath}
		e(t) = \mathrm{e}^{At}(x_0-\hat{x}_0) + \int_0^t \exp(A(t-s))\mathcal{R}_{\hat{\varphi}}(s)\,\mathrm{d}s.
	\end{displaymath}
	Since for any matrix $A$ there exist constants $\alpha \in \ensuremath\mathbb{R}$, $\beta\in\ensuremath\mathbb{R}_+$ such that $\|\exp(At)\|\leq \beta \mathrm{e}^{\alpha t}$, we obtain
	\begin{equation*}
		\begin{aligned}
			\|e(t) \| &\leq  \|  \mathrm{e}^{At} (x_0-\hat{x}_0)  \| + \int_0^t \| \exp(A(t-s))\mathcal{R}_{\hat{\varphi}}(s) \|\,\mathrm{d}s \\
			&\le \beta\mathrm{e}^{\alpha t} \| x_0 -\hat{x}_0\| +  \beta\int_0^t \mathrm{e}^{\alpha(t-s)} \delta(s) \,\mathrm{d}s
		\end{aligned}
	\end{equation*}
	which concludes the proof.

\label{lemma::trpz_rule}
    Assume that the right-hand side $f$ in~\eqref{eq::ode_base} satisfies Assumption~\ref{ass::Lipschitz} and that the ML candidate function $\hat{\varphi}$ is sufficiently smooth. Let $\delta \in \mathcal{C}^3(\mathbb{T}, \ensuremath\mathbb{R})$ with
    \begin{equation*}
        \|\mathcal{R}_{\hat{\varphi}}(t)  \| \le \delta(t)
    \end{equation*} 
    and $\| \frac{\mathrm{d}^2}{\mathrm{d}s^2} \left( \mathrm{e}^{-Ls} \delta(s) \right)\| \le K$ for $s \in \mathbb{T}$. Then 
    \begin{equation*}
        \| \hat{x}(t) - x(t) \| \le \mathrm{e}^{Lt} \|x_0 - \hat{x}(0)\| + \hat{I}_n(t, \delta) + E_\mathrm{Int} \, \text{,} 
    \end{equation*}
    with $\hat{I}_n(t,\delta)$ is the composite trapezoidal rule approximation of $I(t,\delta)$ using $n$ subintervals. The error from the numerical integration is encapsulated in 
	\begin{displaymath}
		E_\mathrm{Int} = \mathrm{e}^{Lt}\frac{Kt^3}{12 n^2}
	\end{displaymath}
